for p,spec in PAT.items():
    prog=spec['prog']
    if spec['melody']:
        mel=MELODY[spec['melody']]
        for b in spec['lead_bars']:
            for i,r in enumerate(eighth):
                off=mel[b][i]; note=TON+off
                add(p,0,b*16+r,note,5)
