            add(p,3,b*16+r,note,8)
    for b in range(4):
        for r in [0,4,8,12]:
            add(p,4,b*16+r,DN,1)
    for b in range(4):
        for r in [4,12]:
            add(p,5,b*16+r,DN,2)
    for b in range(4):
        for r in eighth:
            add(p,6,b*16+r,DN,3)
    for b in range(4):
        for r in spec['hatO']:
            add(p,7,b*16+r,DN,4)

calls.append({'name':'module_save','arguments':{'path':'/workspace/submission/tune.xm','format':'xm'}})

with open('/workspace/build_batch.json','w') as f:
    json.dump(calls,f)
